def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find a solid separator row or column.
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            a, b = grid[:r], grid[r + 1:]
            if len(a) == len(b) and a:
                break
    else:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0:
                a = [row[:c] for row in grid]
                b = [row[c + 1:] for row in grid]
                if a and len(a[0]) == len(b[0]):
                    break

    # The sparser panel is the pattern; zeros in the denser panel erase it.
    count_a = sum(v != 0 for row in a for v in row)
    count_b = sum(v != 0 for row in b for v in row)
    if count_a <= count_b:
        pattern, mask = a, b
    else:
        pattern, mask = b, a

    return [
        [2 if pattern[r][c] != 0 and mask[r][c] != 0 else 0
         for c in range(len(pattern[0]))]
        for r in range(len(pattern))
    ]
